return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Перайдзіце да пошуку ўбудоў','Activate %s' => 'Актываваць %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> патрабуе ўсталявання і актывацыі <strong>%2$s</strong> . <a href="%4$s">%3$s</a>','Enter your code here' => 'Увядзіце свой код тут','Add %s' => 'Дадаць %s','Remove' => 'Зняць','Order number and receipt will be sent to this email address.' => 'Нумар заказу і квітанцыя будуць адпраўлены на гэты адрас электроннай пошты.','Apartment, unit, building, floor, etc.' => 'Кватэра, дом, будынак, паверх і г.д.','Shipping phone' => 'Тэлефон для дастаўкі','Only used for shipping-related questions.' => 'Выкарыстоўваецца толькі для пытанняў, звязаных з дастаўкай.','Single step' => 'Адзін крок','Click to go to the order summary' => 'Націсніце, каб перайсці да зводкі заказу','Cart total:' => 'Усяго ў кошыку:','Proceed to %s' => 'Перайсці да %s','Proceed to contact' => 'Перайсці да кантакту','Proceed to shipping' => 'Прыступайце да адпраўкі','Proceed to billing' => 'Прыступайце да выстаўлення рахункаў','Proceed to payment' => 'Прыступайце да аплаты','Shipping method' => 'Спосаб дастаўкі','Additional notes' => 'Дадатковыя заўвагі','Payment method' => 'Спосаб аплаты','Step %1$s of %2$s' => 'Крок %1$s з %2$s','Change: %s' => 'Змена: %s','Not selected yet.' => 'Яшчэ не выбраны.','Same as shipping address' => 'Такі ж, як адрас дастаўкі','Same as billing address' => 'Такі ж, як адрас для выстаўлення рахункаў','Order summary' => 'Рэзюмэ замовы','Edit cart' => 'Рэдагаваць кошык','Did you mean %s?' => 'Вы мелі на ўвазе %s?','Change email address to: {suggestion-value}' => 'Змяніць адрас электроннай пошты на: {suggestion-value}','This is a required field.' => 'Гэта абавязковае поле.','This is not a valid email address.' => 'Гэта несапраўдны адрас электроннай пошты.','This field does not match the related field value.' => 'Гэта поле не супадае са значэннем звязанага поля.','The CPF number "{cpf_number}" is invalid.' => 'Нумар CPF &quot;{cpf_number}&quot; несапраўдны.','The CNPJ number "{cnpj_number}" is invalid.' => 'Нумар CNPJ &quot;{cnpj_number}&quot; несапраўдны.','(Required)' => '(Абавязкова)','Checkout Header - Desktop' => 'Загаловак касы - працоўны стол','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Адлюстраванне віджэтаў у загалоўку касы для вялікіх экранаў. Адлюстроўваецца толькі пры выкарыстанні загалоўка афармлення плагіна.','Checkout Header - Mobile' => 'Загаловак афармлення замовы - мабільны','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Адлюстраванне віджэтаў пад загалоўкам афармлення замовы для мабільных прылад. Адлюстроўваецца толькі пры выкарыстанні загалоўка афармлення плагіна.','Checkout Sidebar' => 'Бакавая панэль касы','Display widgets on the checkout sidebar after the order summary.' => 'Адлюстраванне віджэтаў на бакавой панэлі афармлення замовы пасля зводкі замовы.','Checkout Order Summary' => 'Рэзюмэ заказу на афармленне заказу','Display widgets inside the order summary at the checkout page.' => 'Адлюстраванне віджэтаў у зводцы замовы на старонцы афармлення заказу.','Checkout Below Place Order' => 'Аформіць заказ. Ніжэй размясціць заказ','Display widgets below the place order button at the checkout page.' => 'Адлюстраванне віджэтаў пад кнопкай размясціць заказ на старонцы афармлення заказу.','Checkout Footer' => 'Ніжні калонтытул касы','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Адлюстраванне віджэтаў у ніжнім калонтытуле касы. Адлюстроўваецца толькі пры выкарыстанні ніжняга калонтытула афармлення замовы плагіна.','Classic' => 'Класіка','Boxed' => 'У скрынцы','Split' => 'Раскол','Minimalist' => 'Мінімалісцкі','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Плагіны Fluid Checkout і Delivery Date ад CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Мы выявілі, што вы выкарыстоўваеце плагіны Delivery &amp; Pickup Date Time для WooCommerce (бясплатныя і PRO) ад CodeRockz. Інтэграцыя з гэтымі ўбудовамі была перанесена ў Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Абнаўленне да PRO','Fluid Checkout database updated successfully' => 'База дадзеных Fluid Checkout паспяхова абноўлена','The database changes where applied successfully.' => 'База дадзеных змяняецца там, дзе паспяхова прыменена.','Dismiss' => 'Звольніць','Fluid Checkout database update' => 'Абнаўленне базы дадзеных Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Неабходныя некаторыя змены ў базе дадзеных. Як і пры любым абнаўленні, мы рэкамендуем вам <strong>зрабіць поўную рэзервовую копію вашага сайта, перш чым працягваць</strong> .','Update database' => 'Абнаўленне базы дадзеных','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout несумяшчальны з макетам касы Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Для працы Fluid Checkout патрэбна класічная форма афармлення замовы на аснове кароткіх кодаў WooCommerce. Пры выкарыстанні Divi Builder для наладжвання выгляду старонкі афармлення замовы класічныя шорткоды замяняюцца карыстацкімі віджэтамі з Divi Builder для кожнай часткі старонкі афармлення замовы. Гэтыя карыстальніцкія віджэты несумяшчальныя з Fluid Checkout.</p><p> Адрэдагуйце старонку афармлення замовы, замяніўшы віджэты Divi Builder на тэкставы віджэт, які змяшчае кароткі код <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'Рэдагаваць старонку афармлення замовы','Read the documentation.' => 'Прачытайце дакументацыю.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Пры выкарыстанні Fluid Checkout неабходна адключыць функцыю шматэтапнай афармлення германізаванай PRO','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Пры выкарыстанні Fluid Checkout шматкрокавая функцыя германізаванага плагіна PRO становіцца непатрэбнай і можа выклікаць <strong>крытычныя памылкі пры апрацоўцы новых заказаў</strong> . Калі ласка, адключыце функцыю шматэтапнай афармлення германізаванай PRO ў наладах плагіна.','Go to Germanized settings' => 'Перайдзіце ў германізаваныя налады','Thanks for choosing Fluid Checkout!' => 'Дзякуй за выбар Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Вы ўжо некаторы час карыстаецеся плагінам. Як вам гэта да гэтага часу?<br> Дайце нам хуткую ацэнку, мы цэнім кожны водгук, і гэта заахвочвае нас працягваць удасканальваць плагін :)','Rate the plugin' => 'Ацаніце плагін','I need help!' => 'Мне патрэбна дапамога!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Некаторыя функцыі WooCommerce Checkout Manager ад Quadlayers могуць не працаваць належным чынам пры выкарыстанні з Fluid Checkout. Прачытайце <a href="%s">нашу дакументацыю</a> для атрымання дадатковай інфармацыі і альтэрнатыўных рашэнняў.','Read documentation' => 'Прачытайце дакументацыю','Don\'t show this again' => 'Не паказваць гэта зноў','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Больш шаблонаў дызайну','Optimized cart page' => 'Аптымізаваная старонка кошыка','Optimized order received / thank you page' => 'Атрыманы аптымізаваны заказ / старонка падзякі','Edit cart contents at checkout page' => 'Рэдагаваць змесціва кошыка на старонцы афармлення замовы','Account matching / user matching' => 'Супастаўленне ўліковых запісаў / супастаўленне карыстальнікаў','Trust symbols on the cart and thank you pages' => 'Сімвалы даверу на старонках кошыка і падзякі','More positions for the coupon code on the checkout page' => 'Больш пазіцый для кода купона на старонцы афармлення замовы','International phone numbers' => 'Міжнародныя нумары тэлефонаў','Gift messages and packing slips' => 'Падарункавыя паведамленні і ўпаковачныя лісткі','Local pickup and in-store collection' => 'Мясцовы самавываз і збор у краме','EU-VAT Assistant' => 'Асістэнт ЕС-ПДВ','I already have it – Hide this offer' => 'У мяне гэта ўжо ёсць - Схаваць гэту прапанову','Activated' => 'Актываваны','Address book' => 'Адрасная кніга','Select an image' => 'Выберыце малюнак','Cart layout' => 'Макет каляскі','Cart optimizations' => 'Аптымізацыя кошыка','Enable cart page optimizations' => 'Уключыць аптымізацыю старонкі кошыка','Header and footer template' => 'Шаблон верхняга і ніжняга калонтытулаў','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Кантралюе, выкарыстоўваць верхні і ніжні калонтытул старонкі без адцягнення ўвагі або захаваць верхні і ніжні калонтытул актыўнай тэмы.','Distraction free header and footer' => 'Верхні і ніжні калонтытулы без адцягнення ўвагі','Theme\'s header and footer' => 'Верхні і ніжні калонтытул тэмы','Cart elements' => 'Элементы каляскі','Make the order summary stay visible on the cart page while scrolling' => 'Зрабіце так, каб зводка замовы заставалася бачнай на старонцы кошыка падчас пракруткі','Coupon codes' => 'Коды купонаў','Hidden' => 'Схаваны','Before the cart items section' => 'Перад раздзелам тавараў кошыка','Inside the cart items section' => 'Унутры раздзела тавараў кошыка','After the cart items section' => 'Пасля раздзела тавараў кошыка','Before the shipping section' => 'Перад раздзелам дастаўкі','After the shipping section' => 'Пасля раздзела дастаўкі','Before the order summary' => 'Перад рэзюмэ замовы','Inside the order summary' => 'Унутры рэзюмэ замовы','Before the order totals' => 'Да сумы замовы','After the order totals' => 'Пасля сумы парадку','After the order summary' => 'Пасля рэзюмэ замовы','Shipping' => 'Дастаўка','Select position where to display the shipping costs and calculator on the cart page.' => 'Выберыце месца для адлюстравання кошту дастаўкі і калькулятара на старонцы кошыка.','Display as a cart section' => 'Паказваць як раздзел кошыка','Cross-sells' => 'Перакрыжаваныя продажу','Select position where to display the cross-sells section on the cart page.' => 'Выберыце месца для адлюстравання раздзела перакрыжаваных продажаў на старонцы кошыка.','Before the cart actions' => 'Перад вазковымі дзеяннямі','After the cart actions' => 'Пасля вазковых дзеянняў','Layout of cross-sell items on the cart page.' => 'Макет тавараў перакрыжаванага продажу на старонцы кошыка.','Optimized horizontal cross-sells layout' => 'Аптымізаваны гарызантальны макет перакрыжаваных продажаў','Theme\'s cross-sells layout' => 'Макет тэмы для перакрыжаваных продажаў','Number of cross-sell items to display on the cart page' => 'Колькасць тавараў перакрыжаванага продажу для адлюстравання на старонцы кошыка','Add widget areas to the cart page' => 'Дадайце вобласці віджэтаў на старонку кошыка','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Гэтыя вобласці віджэтаў выкарыстоўваюцца для дадання сімвалаў даверу і значкоў даверу на старонку кошыка.','Checkout' => 'Каса','Checkout layout' => 'Макет касы','Design template' => 'Шаблон дызайну','Dark mode' => 'Цёмны рэжым','Enable dark mode' => 'Уключыце цёмны рэжым','Logo image' => 'Выява лагатыпа','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Выберыце выяву, якая будзе адлюстроўвацца ў загалоўку старонкі афармлення замовы. Прымяняецца толькі пры выкарыстанні верхніх і ніжніх калонтытулаў, якія не адцягваюць увагу.','Header background color' => 'Колер фону загалоўка','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Выберыце колер фону для загалоўка старонкі афармлення замовы. Прымяняецца толькі пры выкарыстанні верхніх і ніжніх калонтытулаў, якія не адцягваюць увагу.','HTML color value. ie: #f3f3f3' => 'Значэнне колеру HTML. гэта значыць: #f3f3f3','Page background color' => 'Колер фону старонкі','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Выберыце колер фону для старонкі афармлення замовы. Колер нанесены на <em>корпусны</em> элемент.','Footer background color' => 'Колер фону ніжняга калонтытула','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Выберыце колер фону для ніжняга калонтытула старонкі афармлення замовы. Прымяняецца толькі пры выкарыстанні верхніх і ніжніх калонтытулаў, якія не адцягваюць увагу.','Progress bar' => 'Індыкатар прагрэсу','Display the checkout progress bar when using multi-step checkout layout' => 'Адлюстроўваць панэль ходу афармлення афармлення пры выкарыстанні шматэтапнай раскладкі','Make the checkout progress bar stay visible while scrolling' => 'Зрабіце так, каб панэль ходу афармлення замовы заставалася бачнай падчас пракруткі','Express checkout' => 'Экспрэс-касса','Enable the express checkout section' => 'Уключыце раздзел экспрэс-кассы','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Адлюстроўвае раздзел экспрэс-кассы пры афармленні заказу, калі гэтая функцыя ўключана ў падтрымоўваных плацежных шлюзаў.','Display express checkout buttons in one line for larger screens' => 'Адлюстроўвайце кнопкі экспрэс-афармлення ў адзін радок для вялікіх экранаў','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ігнаруйце дадатковыя абавязковыя палі пры аплаце з дапамогай сумяшчальнага аплатнага шлюза экспрэс-кассы','Make the order summary stay visible while scrolling' => 'Зрабіце так, каб зводка замовы заставалася бачнай падчас пракруткі','Choose a background color for the order summary section.' => 'Выберыце колер фону для раздзела зводкі замовы.','Highlight the order totals row in the order summary table' => 'Вылучыце радок выніковай сумы заказу ў табліцы зводкі заказаў','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Найбольш карысна, калі раздзел зводкі заказу не мае вылучанага колеру фону. Можа таксама прымяняцца да старонак &quot;Кошык&quot;, &quot;Атрыманы заказ&quot; і &quot;Прагляд заказа&quot; пры выкарыстанні Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Спасылка на дзеянне ў зводцы заказа пры афармленні заказу.','Edit cart link' => 'Рэдагаваць спасылку на кошык','Cart items count' => 'Колькасць тавараў у кошыку','Link to shop page' => 'Спасылка на старонку крамы','Cart items' => 'Элементы кошыка','Hide cart items errors at the checkout page' => 'Схаваць памылкі тавараў кошыка на старонцы афармлення замовы','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Не паказваць паведамленне пра памылку тавараў у кошыку ў верхняй частцы старонкі афармлення замовы. Пры адпраўцы формы афармлення заказу для завяршэння пакупкі гэтыя паведамленні пра памылкі заўсёды будуць адлюстроўвацца.','Place order' => 'Размясціць заказ','Define the position to display "Place order" and terms checkbox section.' => 'Вызначце пазіцыю для адлюстравання раздзела сцяжка &quot;Размясціць заказ&quot; і ўмоў.','Some options might not be compatible with some plugins and themes.' => 'Некаторыя параметры могуць быць несумяшчальныя з некаторымі ўбудовамі і тэмамі.','Below the payment section' => 'Пад раздзелам аплаты','Below the order summary' => 'Пад зводкай замовы','Both below the payment section and the order summary' => 'Абодва пад раздзелам аплаты і зводкай замовы','Add widget areas to the checkout page' => 'Дадайце вобласці віджэтаў на старонку афармлення замовы','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Гэтыя вобласці віджэтаў выкарыстоўваюцца для дадання сімвалаў даверу і значкоў даверу на старонцы афармлення замовы.','Display the coupon codes section title' => 'Адлюстраванне загалоўка раздзела кодаў купонаў','Select position where to display the coupon codes section on the checkout page.' => 'Выберыце месца для адлюстравання раздзела кодаў купонаў на старонцы афармлення замовы.','Before the checkout steps' => 'Перад тым як разлічыцца','As a substep before payment methods' => 'Як падэтап перад спосабамі аплаты','As a substep after payment methods' => 'Як падэтап пасля спосабаў аплаты','Default button style' => 'Стандартны стыль кнопкі','"Add" link button' => 'Кнопка спасылкі «Дадаць».','Checkout fields' => 'Касавыя палі','Optional fields' => 'Неабавязковыя палі','Hide optional fields behind a link button' => 'Схавайце дадатковыя палі за кнопкай спасылкі','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Рэкамендуецца трымаць гэты параметр адзначаным, каб паменшыць колькасць адкрытых палёў уводу, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">прачытайце даследаванне</a> .','Do not hide "Address line 2" fields behind a link button' => 'Не хавайце палі «Адрасны радок 2» за кнопкай спасылкі','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Рэкамендуецца толькі тады, калі большасці кліентаў патрэбна поле «Адрас, радок 2» або калі правільны адрас дастаўкі мае вырашальнае значэнне (напрыклад, пры дастаўцы ежы і іншых прадуктаў, якія хутка псуюцца).','Billing address' => 'Плацежны адрас','Select position where to display the billing address section on the checkout page.' => 'Выберыце месца для адлюстравання раздзела плацежнага адраса на старонцы афармлення замовы.','As a step before shipping' => 'Як этап перад адпраўкай','As a sub-step before the shipping address section' => 'Як падэтап перад раздзелам адраса дастаўкі','As a sub-step after the shipping address section' => 'У якасці падэтапу пасля раздзела адраса дастаўкі','As a step after shipping' => 'Як крок пасля адпраўкі','As a sub-step before the payment section' => 'Як падэтап перад раздзелам аплаты','Force billing and shipping addresses to the same (single section)' => 'Прымусова збліжаць адрасы выстаўлення рахункаў і дастаўкі (адзіны раздзел)','Checkbox for "Same as shipping/billing address" checked by default' => 'Па змаўчанні пастаўлены сцяжок &quot;Такі ж, што і адрас дастаўкі/выстаўлення рахункаў&quot;.','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Сцяжок &quot;Такі ж, што і адрас дастаўкі&quot; будзе пазначаны па змаўчанні, калі раздзел адраса дастаўкі адлюстроўваецца першым.<br> Сцяжок &quot;Такі ж, што і адрас для выстаўлення рахункаў&quot; будзе пазначаны па змаўчанні, калі раздзел з адрасам для выстаўлення рахункаў адлюстроўваецца першым.<br> Рэкамендуецца пакінуць гэты параметр адзначаным, каб значна паменшыць колькасць адкрытых палёў уводу пры афармленні заказу, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">прачытайце даследаванне</a> .','Highlight the billing address section in the checkout form' => 'Вылучыце раздзел плацежнага адрасу ў форме афармлення замовы','Shipping address' => 'Адрас дастаўкі','Highlight the shipping address section in the checkout form' => 'Вылучыце раздзел адраса дастаўкі ў форме афармлення замовы','Shipping methods' => 'Спосабы дастаўкі','Choose in which position to display the shipping methods section.' => 'Выберыце, у якой пазіцыі адлюстроўваць раздзел спосабаў дастаўкі.','Before shipping address' => 'Перад адпраўкай адрас','After shipping address' => 'Пасля дастаўкі адрас','Local pickup' => 'Мясцовы пікап','Removes shipping address section when a local pickup shipping method is selected.' => 'Выдаляе раздзел адраса дастаўкі, калі абраны спосаб дастаўкі ў мясцовым парадку.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Замяняе адрас дастаўкі месцазнаходжаннем пункта самавывазу, калі выбраны мясцовы спосаб дастаўкі.','Choose which address to save as the shipping address for local pickup orders.' => 'Выберыце, які адрас захаваць у якасці адраса дастаўкі для мясцовых заказаў.','Save the selected pickup location' => 'Захавайце абранае месца самавывазу','Save same as the billing address' => 'Захаваць гэтак жа, як плацежны адрас','Do not save any shipping address' => 'Не захоўвайце адрас дастаўкі','Company name field for shipping address' => 'Поле назвы кампаніі для адраса дастаўкі','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Змяніце бачнасць поля з назвай кампаніі для раздзела адраса дастаўкі ў форме афармлення замовы.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Калі поле ўстаноўлена як &quot;неабавязковае&quot;, што з&#39;яўляецца станам бачнасці па змаўчанні, ніякія змены не будуць ужытыя, каб дазволіць іншым плагінам прымяняць любыя неабходныя змены.','Hidden (remove field)' => 'Схавана (выдаліць поле)','Optional' => 'Дадаткова','Required' => 'абавязковы','Add shipping phone field to the checkout form.' => 'Дадайце поле тэлефона дастаўкі ў форму афармлення заказу.','Choose in which step to display the shipping phone field.' => 'Выберыце, на якім этапе адлюстроўваць поле тэлефона дастаўкі.','Contact step' => 'Крок кантакту','Billing phone' => 'Разліковы тэлефон','Add billing phone field to the checkout form.' => 'Дадайце поле тэлефона для аплаты ў форму афармлення замовы.','Choose in which step to display the billing phone field.' => 'Выберыце, на якім этапе адлюстроўваць поле тэлефона для аплаты.','Show country code beside the flag' => 'Паказаць код краіны побач са сцягам','Show an example of a valid phone number inside phone fields' => 'Пакажыце прыклад сапраўднага нумара тэлефона ўнутры палёў тэлефона','Do not change placeholders' => 'Не мяняйце запаўняльнікі','Show if not defined' => 'Паказаць, калі не вызначана','Always show' => 'Заўсёды паказваць','Order notes' => 'Заўвагі','Define the visibility of the additional order notes field.' => 'Вызначце бачнасць поля дадатковых заўваг да замовы.','Gift options' => 'Варыянты падарункаў','Allow customers to add a gift message and other gift related options to the order.' => 'Дазвольце кліентам дадаваць у заказ паведамленне аб падарунку і іншыя параметры, звязаныя з падарункам.','Display the gift message as part of the order details table instead of a separate section' => 'Адлюстроўвайце паведамленне аб падарунку як частку табліцы дэталяў замовы, а не ў асобным раздзеле','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Гэты параметр уплывае на старонку пацверджання замовы (старонку падзякі) і дэталі замовы на старонках уліковых запісаў, электронных лістах і ўпаковачных лістах.','Account matching' => 'Супадзенне ўліковых запісаў','Enable the account matching feature' => 'Уключыце функцыю супастаўлення ўліковых запісаў','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Звязвайце заказы гасцявога кліента з яго існуючым уліковым запісам, калі ўліковы запіс з кантактнымі дадзенымі кліента ўжо існуе.','Display message when an account exists with the email address provided' => 'Паказаць паведамленне, калі існуе ўліковы запіс з указаным адрасам электроннай пошты','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Замяняе палі для стварэння ўліковага запісу апавяшчэннем і магчымасцю ўваходу. У некаторых сітуацыях можа быць рэкамендавана пакінуць гэту опцыю адключанай, каб абараніць канфідэнцыяльнасць кліентаў.','Dashboard' => 'Прыборная панэль','Integrations' => 'Інтэграцыі','License keys' => 'Ліцэнзійныя ключы','Visit our website for more information about our plugins and add-ons.' => 'Наведайце наш вэб-сайт для атрымання дадатковай інфармацыі аб нашых убудовах і дапаўненнях.','Order pay page' => 'Старонка аплаты замовы','Order pay' => 'Заказаць аплату','Enable order pay page optimizations' => 'Уключыць аптымізацыю старонкі аплаты замовы','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Змяняе макет старонкі аплаты заказаў для існуючых заказаў, якія чакаюць аплаты ад кліента.','Add widget areas to the order pay page' => 'Дадайце вобласці віджэтаў на старонку аплаты замовы','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Гэтыя вобласці віджэтаў выкарыстоўваюцца для дадання сімвалаў даверу і значкоў даверу на старонцы аплаты замовы.','Thank you page & order details layout' => 'Макет старонкі падзякі і звестак пра заказ','Order details optimizations' => 'Аптымізацыя дэталяў замовы','Enable thank you page and order details optimizations' => 'Уключыце аптымізацыю старонкі падзякі і дэталі замовы','Changes the layout of order details on the thank you page and account pages.' => 'Змяняе размяшчэнне дэталяў замовы на старонцы падзякі і ўліковага запісу.','Enable order details customizations on email notifications' => 'Уключыць налады дэталяў замовы ў паведамленнях па электроннай пошце','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Паказаць новыя раздзелы і змяніць парадак раздзелаў у паведамленнях па электроннай пошце. Стылі дэталяў замовы ў паведамленнях па электроннай пошце застаюцца нязменнымі.','Thank you page' => 'Старонка падзякі','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Гэтыя параметры ўплываюць на старонку падзякі, таксама вядомую як старонкі атрыманага заказу або старонкі пацверджання заказу.','Order details layout' => 'Макет дэталяў замовы','Display the order details with wide layout on the thank you page' => 'Адлюструйце дэталі замовы шырокім макетам на старонцы падзякі','Add widget areas to the thank you page' => 'Дадайце вобласці віджэтаў на старонку падзякі','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Гэтыя вобласці віджэтаў выкарыстоўваюцца для дадання сімвалаў даверу і значкоў даверу на старонку падзякі.','Order actions' => 'Заказ дзеянняў','Choose in which position to display the order actions.' => 'Выберыце, у якой пазіцыі адлюстроўваць дзеянні замовы.','Inside the order overview' => 'Унутры агляду парадку','After the order overview' => 'Пасля агляду замовы','After order sections' => 'Пасля замовы раздзелаў','Order status' => 'Статус замовы','Display the order status progress bar' => 'Адлюстраванне панэлі стану замовы','Choose in which position to display the section.' => 'Выберыце, у якім становішчы адлюстроўваць раздзел.','After the order overview and payment instructions' => 'Пасля агляду замовы і інструкцый па аплаце','Before the order items section' => 'Перад раздзелам тавараў замовы','Inside the order items section' => 'Унутры раздзела тавараў замовы','After the order items section' => 'Пасля раздзела элементаў замовы','On the sidebar' => 'На бакавой панэлі','Order downloads' => 'Замовіць загрузку','Gift message' => 'Паведамленне аб падарунку','Tools' => 'інструменты','Troubleshooting' => 'Ліквідацыю непаладак','Debug options' => 'Параметры адладкі','Debug mode' => 'Рэжым адладкі','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Выкарыстанне рэжыму адладкі ўплывае на прадукцыйнасць сайта. Выкарыстоўвайце гэты параметр толькі падчас пошуку непаладак.','Load unminified assets' => 'Загрузіць немініфікаваныя актывы','Enhanced select fields' => 'Палепшаныя палі выбару','Fix automatic zoom-in on form fields' => 'Выправіць аўтаматычнае павелічэнне палёў формы','Set <code>font-size</code> inside form fields to 16px' => 'Усталюйце <code>font-size</code> ўнутры палёў формы на 16 пікселяў','Fluid Checkout' => 'Выпіска вадкасці','Settings' => 'Налады','Support' => 'Падтрымка','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Абнавіцеся да PRO</a> , каб разблакіраваць дадатковыя магчымасці.','(PRO)' => '(PRO)','(experimental)' => '(эксперыментальны)','Please verify your phone number.' => 'Калі ласка, пацвердзіце свой нумар тэлефона.','The Bluehost Plugin' => 'Убудова Bluehost','Custom fields' => 'Карыстальніцкія палі','Enable custom shipping email field' => 'Уключыць карыстальніцкае поле электроннай пошты для дастаўкі','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Калі ўключана, поле электроннай пошты для дастаўкі з плагіна Bluehost будзе дададзена ў форму афармлення замовы.','Captcha Pro by BestWebSoft' => 'Captcha Pro ад BestWebSoft','Captcha position' => 'Пазіцыя Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Вызначце пазіцыю для адлюстравання раздзела captcha. Некаторыя пазіцыі могуць не працаваць у залежнасці ад абранага тыпу капчу.','Selecting a pickup point is required before proceeding.' => 'Перш чым працягваць, неабходна выбраць пункт адпраўлення.','Pickup point' => 'Пункт самавывазу','Pickup point not selected yet.' => 'Пункт адпраўлення яшчэ не выбраны.','Pickup point:' => 'Пункт выдачы:','Mailchimp for WooCommerce' => 'Mailchimp для WooCommerce','Subscribe checkbox' => 'Сцяжок «Падпісацца».','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Перавызначце пазіцыю для сцяжка «Падпісацца» на старонцы афармлення заказу і заўсёды паказвайце яго на этапе кантакту','Before Shipping Address' => 'Перад адрасам дастаўкі','(originally "%s")' => '(першапачаткова &quot;%s&quot;)','After Shipping Address' => 'Пасля адрасу дастаўкі','Selecting a collection point is required when shipping with FermoPoint.' => 'Пры дастаўцы з FermoPoint неабходна выбраць пункт прыёму.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Калі пазначана, паведамляе карыстальнікам аб памылках друку ў электроннай пошце. (Гэтая функцыя была адключана, таму што яе прапануе Fluid Checkout. Змены гэтай опцыі не ўступяць у сілу)','Enable Mail Check: (disabled feature)' => 'Уключыць праверку пошты: (адключаная функцыя)','Carrier:' => 'Перавозчык:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - Маркетынг электроннай пошты WooCommerce','Sign up checkbox position' => 'Пазіцыя сцяжка &quot;Зарэгістравацца&quot;.','Move the sign up checkbox to the contact step' => 'Перамясціце сцяжок рэгістрацыі на этап кантактаў','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Калі ўключана, сцяжок будзе перамешчаны на этап кантакту незалежна ад месца адлюстравання, вызначанага ў наладах убудовы Sendinblue.','Theme Betheme' => 'Тэма Betheme','Checkout progress' => 'Ход афармлення замовы','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Вывядзіце раздзел этапаў афармлення замовы з Betheme на старонкі афармлення замовы, кошыка і атрыманых заказаў.','Theme Fennik' => 'Тэма феннік','Breadcrumbs' => 'Паніровачныя сухары','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Вывядзіце раздзел паніровачных сухароў з тэмы Fennik пры выкарыстанні верхняга і ніжняга калонтытулаў Fluid Checkout.','Theme Go' => 'Тэма Go','My account layout' => 'Макет майго акаўнта','Enable wide layout on "My account" page.' => 'Уключыць шырокі макет на старонцы «Мой рахунак».','Theme Impreza' => 'Тэма імпрэза','Header' => 'Загаловак','Spacing for site header at the checkout page (in pixels)' => 'Інтэрвал для загалоўка сайта на старонцы афармлення замовы (у пікселях)','Only applicable when using the Impreza theme header at the checkout page.' => 'Дастасавальна толькі пры выкарыстанні загалоўка тэмы Impreza на старонцы афармлення замовы.','Theme Kapee' => 'Тэма капі','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Вывядзіце раздзел этапаў афармлення замовы з тэмы Kapee на старонкі афармлення замовы, кошыка і атрыманых заказаў.','Theme Porto' => 'Тэма Порту','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Вывядзіце раздзел этапаў афармлення замовы з тэмы Porto на старонкі афармлення замовы, кошыка і атрыманых заказаў.','Theme Pressmart' => 'Тэма Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Вывядзіце раздзел этапаў афармлення замовы з тэмы Pressmart на старонкі афармлення замовы, кошыка і атрыманых заказаў.','Theme The Gem' => 'Тэма Каштоўны камень','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Вывядзіце раздзел этапаў афармлення замовы з тэмы The Gem пры выкарыстанні верхняга і ніжняга калонтытулаў Fluid Checkout.','Theme Woodmart' => 'Тэма Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Вывядзіце раздзел этапаў афармлення замовы з тэмы Woodmart пры выкарыстанні верхняга і ніжняга калонтытулаў Fluid Checkout.','Checkout options' => 'Варыянты афармлення замовы','Disable the theme checkout options' => 'Адключыце параметры афармлення тэмы','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Параметры адлюстравання выявы прадукту, поля колькасці, кнопкі выдалення і спасылкі на старонку прадукту, дададзеныя тэмай, адключаны па змаўчанні.','Theme Atomion' => 'Тэма Atomion','Order progress' => 'Ход выканання замовы','Display order progress from the theme' => 'Адлюстраванне ходу замовы з тэмы','Display the form field labels visible on the page' => 'Паказаць меткі палёў формы, бачныя на старонцы','It is recommended to keep this option enabled for a better user experience.' => 'Рэкамендуецца трымаць гэты параметр уключаным для лепшага карыстання.','Theme ZK Nito' => 'Тэма ZK Nito','Add extra fields to the checkout form' => 'Дадайце дадатковыя палі ў форму афармлення замовы','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Дадае дадатковае поле электроннай пошты для дастаўкі і тэлефона для дастаўкі ў раздзел адраса дастаўкі.','Go to the home page' => 'Перайсці на галоўную старонку','Skip to content' => 'Перайсці да зместу','Create an account' => 'Стварыць уліковы запіс','Log in to your account' => 'Увайдзіце ў свой уліковы запіс','Already have an account?' => 'У вас ужо ёсць уліковы запіс?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Вы ўвайшлі як %1$s. <a href="%2$s">Выйсці</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Ваша замова мае агульную суму %s. Ніякіх дадатковых плацяжоў не патрабуецца.','Close and continue with checkout' => 'Зачыніць і працягнуць афармленне заказу','Continue' => 'Працягнуць','Parcel terminal' => 'Пасылачны тэрмінал','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Гэты віджэт быў заменены на Fluid Checkout.</p><p> Пры выкарыстанні Fluid Checkout старонка афармлення замовы павінна выкарыстоўваць арыгінальны кароткі код WooCommerce <code>[woocommerce_checkout]</code> , каб працаваць належным чынам.</p><p> Для атрымання дадатковай інфармацыі наведайце дакументацыю Fluid Checkout.</p>','Theme The7' => 'Тэма The7','Additional header sections' => 'Дадатковыя раздзелы загалоўка','Output additional header sections if enabled in the theme settings.' => 'Выводзіць дадатковыя раздзелы загалоўка, калі гэта ўключана ў наладах тэмы.','More information' => 'Дадатковая інфармацыя','Pick a Locker' => 'Выберыце шафку','Page template' => 'Шаблон старонкі','Use `Order confirmation` page template for block-based themes' => 'Выкарыстоўвайце шаблон старонкі «Пацверджанне замовы» для блокавых тэм','Only applies when using a block-based theme.' => 'Дзейнічае толькі пры выкарыстанні блокавай тэмы.','WooCommerce Stripe Gateway' => 'Шлюз WooCommerce Stripe','Payment form' => 'Форма аплаты','Apply styles to the Stripe payment form fields' => 'Ужыванне стыляў да палёў плацежнай формы Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Калі ўключана, Fluid Checkout будзе ўжываць стылі, аптымізаваныя для сумяшчальнасці з плагінам. Вы можаце адключыць гэту функцыю, калі выкарыстоўваеце ўласныя стылі для палёў плацежнай формы Stripe.','Theme Nyture' => 'Тэма Найтура','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Вывесці раздзел крокаў афармлення замовы з тэмы Nyture пры выкарыстанні Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Дазваляе кліентам ажыццяўляць аплату за заказы, якія былі створаны ўручную адміністратарам крамы або не былі завершаны падчас афармлення замовы.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Убудова WooCommerce Checkout Manager ад Quadlayers не сумяшчальная з Fluid Checkout.','Company name field for billing address' => 'Поле назвы кампаніі для адраса для выстаўлення рахункаў','Change visibility for the company name field for the billing address section on the checkout form.' => 'Змяніць бачнасць поля назвы кампаніі ў раздзеле плацежнага адраса ў форме афармлення замовы.','Theme Bookshelf' => 'Тэматычная кніжная паліца','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Вывесці раздзел крокаў афармлення замовы з тэмы Bookshelf пры выкарыстанні Fluid Checkout.','Account password' => 'Пароль уліковага запісу','An account will be created with the information provided at checkout when completing the order.' => 'Уліковы запіс будзе створаны з выкарыстаннем інфармацыі, указанай пры афармленні замовы.','Choose the style of the progress bar.' => 'Выберыце стыль індыкатара прагрэсу.','Bars' => 'Бары','Theme Ireca' => 'Тэма Ірэка','WooCommerce page layout' => 'Макет старонкі WooCommerce','Force wide layout on WooCommerce pages' => 'Прымусовае шырокае размяшчэнне на старонках WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Гэта гарантуе, што раздзел зместу на старонках WooCommerce, уключаючы афармленне замовы, кошык, атрыманне замовы, аплату замовы і старонкі ўліковага запісу, не будзе занадта вузкім.','WooCommerce Smart Coupons' => 'Разумныя купоны WooCommerce','Position on checkout page' => 'Пазіцыя на старонцы афармлення замовы','Choose where to display the available coupons section on the checkout page.' => 'Выберыце, дзе на старонцы афармлення замовы адлюстроўваць раздзел даступных купонаў.','Before the progress bar' => 'Перад індыкатарам прагрэсу','After the progress bar' => 'Пасля індыкатара прагрэсу','Before coupon codes section' => 'Раздзел перад кодамі купонаў','Format phone numbers according to the rules for each country.' => 'Фарматуйце нумары тэлефонаў у адпаведнасці з правіламі кожнай краіны.','Use precise phone number validation' => 'Выкарыстоўвайце праверку дакладнага нумара тэлефона','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Гэта эксперыментальная функцыя, і яна можа працаваць неналежным чынам ва ўсіх наладах. Выкарыстоўвайце яе асцярожна.','Phone number validation types used when precise validation is enabled.' => 'Тыпы праверкі нумара тэлефона, якія выкарыстоўваюцца, калі ўключана дакладная праверка.','Mobile' => 'Мабільны','Fixed line' => 'Фіксаваная лінія','Toll free' => 'Бясплатны званок','Contact' => 'Кантакт','Multi step' => 'Шматступенчаты','2 columns' => '2 слупкі','1 column' => '1 слупок','Before checkout steps' => 'Этапы перад афармленнем замовы','Or' => 'Або','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Пры выкарыстанні макета афармлення замовы <em>«1 слупок»</em> гэтая опцыя заўсёды мае значэнне <em>«Перад крокамі афармлення замовы»</em> і таксама распаўсюджваецца на выгляд для камп&#39;ютара.','Position for the extra order summary section on mobile.' => 'Размясціць дадатковы раздзел зводкі замовы на мабільным тэлефоне.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Опцыя <em>«У загалоўку сайта»</em> дзейнічае толькі пры выкарыстанні загалоўка без адцягваючых элементаў.','On the site header (requires distraction-free header)' => 'У загалоўку сайта (патрабуецца загаловак без адцягненняў)','Initial state for the expansible order summary section on mobile.' => 'Пачатковы стан пашыральнага раздзела зводкі замовы на мабільным тэлефоне.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Згодна з патрабаваннямі рэгулятара, мы рэкамендуем усталяваць <em>пашыраны</em> рэжым для наступных краін: <strong>Германія</strong> , <strong>Аўстрыя</strong> , <strong>Швейцарыя</strong> , <strong>Нідэрланды</strong> , <strong>Польшча</strong> , <strong>Бельгія</strong> і <strong>Францыя</strong> .','Collapsed' => 'Згорнута','Expanded' => 'Пашырана','Do not show' => 'Не паказваць','yes' => 'так','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Поле тэлефона дастаўкі можа быць прымусова запаўнена як «абавязковае», калі раздзел адраса для выстаўлення рахункаў адлюстроўваецца пасля раздзела адраса дастаўкі, і поле тэлефона для выстаўлення рахункаў усталявана як «абавязковае». Гэта неабходна для таго, каб адрас дастаўкі можна было скапіяваць у адрас для выстаўлення рахункаў, калі гэтая опцыя адзначана, інакш кліент можа не мець магчымасці запоўніць форму афармлення замовы.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Поле нумара тэлефона для выстаўлення рахункаў можа быць прымусова запаўнена як «абавязковае», калі раздзел адраса для выстаўлення рахункаў адлюстроўваецца перад раздзелам адраса дастаўкі, і поле нумара тэлефона дастаўкі ўстаноўлена як «абавязковае». Гэта неабходна для таго, каб адрас дастаўкі можна было скапіяваць у адрас для выстаўлення рахункаў, калі гэтая опцыя ўключана, інакш кліент можа не мець магчымасці запоўніць форму афармлення замовы.','Settings profiles' => 'Профілі налад','Settings profile' => 'Профіль налад','You do not have permission to perform this action.' => 'У вас няма дазволу на выкананне гэтага дзеяння.','You do not have permission to activate plugins.' => 'У вас няма дазволу на актывацыю плагінаў.','Missing plugin.' => 'Адсутнічае плагін.','Plugin activated.' => 'Плагін актываваны.','The following changes will be applied:' => 'Будуць ужытыя наступныя змены:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Пачынаючы з версіі Fluid Checkout 5.0, налады захоўваюцца па-іншаму. Састарэлыя параметры ўсё яшчэ захоўваюцца ў базе дадзеных, каб пры неабходнасці можна было вярнуцца да папярэдніх версій.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Ваша крама працуе каля 2 тыдняў з новымі наладах, таму вы можаце ачысціць састарэлыя параметры, якія захоўваюцца ў базе дадзеных. Звярніце ўвагу, што пасля ачысткі, калі вам трэба будзе вярнуцца да папярэдніх версій плагіна, для ўсіх налад будуць выкарыстоўвацца значэнні па змаўчанні.','Fluid Checkout settings cleanup' => 'Ачыстка налад Fluid Checkout','Delete leftover options' => 'Выдаліць рэшткі варыянтаў','Help us improve Fluid Checkout' => 'Дапамажыце нам палепшыць Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Дзяліцеся ананімнымі справаздачамі аб асяроддзі сайта з дапамогай Fluid Checkout, каб атрымаць больш хуткую падтрымку і дапамагчы нам палепшыць сумяшчальнасць і вымераць уплыў. Дадзеныя кліентаў, карыстальнікаў або канфідэнцыйныя даныя не ўключаюцца. Вы можаце выбраць, што будзе абагулена, у любы час у наладах інструментаў.','Enable site environment reports' => 'Уключыць справаздачы аб асяроддзі сайта','Review settings' => 'Праглядзець налады','This preview has expired. Reload the admin page to start a new preview.' => 'Тэрмін дзеяння гэтага папярэдняга прагляду скончыўся. Перазагрузіце старонку адміністратара, каб пачаць новы папярэдні прагляд.','Preview expired' => 'Папярэдні прагляд скончыўся','Orders cannot be placed in the preview.' => 'Заказы нельга размяшчаць у рэжыме папярэдняга прагляду.','Logging in is not available in the preview.' => 'Уваход у сістэму недаступны ў папярэднім праглядзе.','Accounts cannot be created in the preview.' => 'У папярэднім праглядзе ўліковыя запісы ствараць нельга.','Requests to other sites are blocked in the preview.' => 'Запыты да іншых сайтаў блакуюцца ў папярэднім праглядзе.','Processing…' => 'Апрацоўка…','Something went wrong. Please try again.' => 'Нешта пайшло не так. Паўтарыце спробу.','Activate plugin' => 'Актываваць плагін','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Поўны пакет для афармлення замовы','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Усе PRO-функцыі + усе дапаўненні, адна цана. Шаблоны дызайну, аптымізаваны кошык і старонкі атрыманых заказаў, супастаўленне акаўнтаў і многае іншае.','Optimized order pay page' => 'Аптымізаваная старонка аплаты замовы','Express checkout buttons from supported payment methods' => 'Кнопкі экспрэс-аплаты з падтрымоўваных спосабаў аплаты','Delayed account creation' => 'Затрымка стварэння ўліковага запісу','Address autocomplete with Google Maps APIs' => 'Аўтазапаўненне адрасоў з дапамогай API Карт Google','Multiple saved addresses with the address book' => 'Некалькі захаваных адрасоў у адраснай кнізе','EU-VAT assistant' => 'Памочнік па ПДВ ЕС','Hide this section' => 'Схаваць гэты раздзел','Learn more' => 'Даведайцеся больш','Get early access' => 'Атрымайце ранні доступ','Activate add-on' => 'Актываваць дадатак','Get more out of your checkout journey' => 'Атрымайце максімум ад афармлення замовы','Test API key' => 'Тэставы ключ API','Guided setup' => 'Кіраваная налада','Options' => 'Варыянты','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Наладзьце макет і дызайн у <a href="%s">параметрах афармлення замовы</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Уключыць афармленне замовы гасцямі і/або прагляд <a href="%s">налад уліковых запісаў кліентаў</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Уключыце аптымізаваны <a href="%1$s">кошык</a> , старонкі <a href="%2$s">падзякі</a> і <a href="%3$s">аплаты замовы</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Уключыць <a href="%s">аўтазапаўненне адрасоў</a> з Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Уключыце некалькі захаваных адрасоў з дапамогай <a href="%s">адраснай кнігі</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Праверце, ці ёсць даступныя якія-небудзь <a href="%s">варыянты інтэграцыі</a> для тэмы або іншых усталяваных вамі плагінаў.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Атрымайце больш хуткую падтрымку і дапамажыце нам палепшыць сумяшчальнасць і вымераць уплыў. <a href="%s">Уключыце адсочванне выкарыстання</a> ў наладах інструментаў.','Missing settings tab.' => 'Адсутнічае ўкладка налад.','Getting started' => 'Пачатак працы','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Выдатна! Ваша старонка афармлення замовы цяпер працуе на Fluid Checkout.</strong> Вось некалькі крокаў, каб пачаць:','Completed' => 'Завершана','Preview report data' => 'Папярэдні прагляд дадзеных справаздачы','Send now' => 'Адправіць зараз','Auto-detect' => 'Аўтаматычнае вызначэнне','Afrikaans' => 'Афрыкаанс','Albanian' => 'Албанская','Amharic' => 'Амхарская','Arabic' => 'Арабская','Armenian' => 'Армянская','Azerbaijani' => 'Азербайджанская','Basque' => 'Баскская','Belarusian' => 'Беларуская','Bengali' => 'Бенгальская','Bosnian' => 'Баснійскі','Bulgarian' => 'Балгарская','Burmese' => 'Бірманская','Catalan' => 'Каталонская','Chinese' => 'Кітайская','Chinese (Simplified)' => 'Кітайская (спрошчаная)','Chinese (Hong Kong)' => 'Кітайская (Ганконг)','Chinese (Traditional)' => 'Кітайская (традыцыйная)','Croatian' => 'Харвацкая','Czech' => 'Чэшская','Danish' => 'Дацкая','Dutch' => 'галандская','English' => 'Англійская','English (Australian)' => 'Англійская (аўстралійская)','English (Great Britain)' => 'Англійская (Вялікабрытанія)','Estonian' => 'Эстонская','Farsi' => 'Фарсі','Finnish' => 'Фінская','Filipino' => 'Філіпінская','French' => 'Французская','French (Canadian)' => 'Французская (канадская)','Galician' => 'Галісійская','Georgian' => 'Грузінская','German' => 'Нямецкая','Greek' => 'Грэчаская','Gujarati' => 'Гуджараці','Hebrew' => 'Іўрыт','Hindi' => 'Хіндзі','Hungarian' => 'Венгерская','Icelandic' => 'Ісландская','Indonesian' => 'Інданезійская','Italian' => 'Італьянская','Japanese' => 'Японская','Kannada' => 'Каннада','Kazakh' => 'Казахская','Khmer' => 'Кхмерская','Korean' => 'Карэйская','Kyrgyz' => 'Кыргызская','Lao' => 'Лао','Latvian' => 'Латышская','Lithuanian' => 'Літоўская','Macedonian' => 'Македонская','Malay' => 'Малайская','Malayalam' => 'Малаялам','Marathi' => 'Маратхі','Mongolian' => 'Мангольская','Nepali' => 'Непальская','Norwegian' => 'Нарвежская','Polish' => 'Польская','Portuguese' => 'Партугальская','Portuguese (Brazil)' => 'Партугальская (Бразілія)','Portuguese (Portugal)' => 'Партугальская (Партугалія)','Punjabi' => 'Панджабі','Romanian' => 'Румынская','Russian' => 'Руская','Serbian' => 'Сербская','Sinhalese' => 'Сінгальская','Slovak' => 'Славацкая','Slovenian' => 'Славенская','Spanish' => 'Іспанская','Spanish (Latin America)' => 'Іспанская (Лацінская Амерыка)','Swahili' => 'Суахілі','Swedish' => 'Шведская','Tamil' => 'Тамільская','Telugu' => 'Тэлугу','Thai' => 'Тайская','Turkish' => 'Турэцкая','Ukrainian' => 'украінская','Urdu' => 'Урду','Vietnamese' => 'В&#39;етнамская','Zulu' => 'Зулу','Google address autocomplete' => 'Аўтазапаўненне адраса Google','Google Places API version' => 'Версія API Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Выберыце, якую версію Google Places API выкарыстоўваць. Мы рэкамендуем як мага хутчэй перайсці на новы Places API.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Мы рэкамендуем выкарыстоўваць «Places API (новы)», бо з 1 сакавіка 2025 года Google перавядзе версію «Places API (састарэлая)» у статус «Старая», гэта значыць, што вы больш не зможаце ўключыць гэтую службу для новых ключоў API, і гэтая версія API з часам будзе недаступная. Існуючыя ўліковыя запісы, якія ўжо выкарыстоўваюць састарэлы API, могуць працягваць працаваць без перапынкаў.','(Recommended)' => '(Рэкамендуецца)','Google API key' => 'Ключ API Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Устаўце свой ключ API Google і выкарыстоўвайце кнопку «Праверыць», каб пераканацца, што ён працуе для гэтага вэб-сайта. Пераканайцеся, што ключ сапраўдны і дазволены для вашага дамена, інакш поле адраса можа быць заблакавана, што перашкодзіць кліентам аформіць заказ.','Enable Google address autocomplete' => 'Уключыць аўтазапаўненне адрасоў Google','Enable address autocompletion using the Google Maps APIs.' => 'Уключыце аўтазапаўненне адрасоў з дапамогай API Карт Google.','Google API language' => 'Мова API Google','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Гэтая мова будзе выкарыстоўвацца для адлюстравання прапаноў адрасоў API Google Places, і адрасы таксама будуць аўтаматычна запаўняцца на гэтай мове.','Result types' => 'Тыпы вынікаў','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Пакіньце поле пустым, каб прымаць любыя тыпы вынікаў, што звычайна дае лепшыя вынікі супадзення. <a href="%s" target="_blank">Глядзіце дакументацыю для атрымання дадатковай інфармацыі</a> .<br> Выберыце да 5 тыпаў вынікаў пошуку адрасоў, якія будуць вяртацца ў палях аўтазапаўнення адрасоў.<br> Каб даведацца больш пра <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">падтрымоўваныя тыпы</a> , наведайце дакументацыю Google Maps.','Result types (Legacy API)' => 'Тыпы вынікаў (Старэйшы API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Які тып вынікаў пошуку адрасоў вяртаць пры выкарыстанні Places API (Legacy).<br> Каб даведацца больш пра <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">падтрымоўваныя тыпы,</a> азнаёмцеся з дакументацыяй па Legacy Google Places API.','Company fields' => 'Палі кампаніі','Enable autocomplete for the company name if available' => 'Уключыць аўтазапаўненне для назвы кампаніі, калі даступна','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Уключыць аўтаматычнае запаўненне поля кампаніі інфармацыяй пра назву кампаніі пры вяртанні з API Карт Google.','Business search' => 'Пошук бізнесу','Enable search for businesses in the company field' => 'Уключыць пошук прадпрыемстваў у полі кампаніі','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Уключыць падказку адрасоў, звязаных з кампаніяй, пры ўводзе ў поле кампаніі, а затым аўтаматычна запаўняць усе палі адрасоў, калі кампанія будзе выбрана з прапанаваных.','Company result types' => 'Тыпы вынікаў кампаніі','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Выберыце да 5 тыпаў вынікаў пошуку адрасоў, якія будуць вяртацца пры аўтазапаўненні палёў кампаніі.<br> Рэкамендаванае значэнне — <code>establishment</code> , якое ўключае большасць тыпаў бізнесу.<br> Пакіньце поле пустым, каб прымаць любыя тыпы вынікаў, у тым ліку вынікі, не звязаныя з бізнесам.<br> Каб даведацца больш пра <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">падтрымоўваныя тыпы</a> , наведайце дакументацыю Google Maps.','Google logo' => 'Лагатып Google','Show text and logo "Powered by Google"' => 'Паказаць тэкст і лагатып «Працуе на базе Google»','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Калі гэты пункт пазначаны, унізе поля з прапановамі аўтазапаўнення адрасоў будзе адлюстроўвацца тэкст і лагатып «Працуе на базе Google».','Brasil API address autocomplete' => 'Аўтазапаўненне адрасоў Brasil API','Brasil API' => 'Бразільскі API','Enable Brasil API address autocomplete for CEP fields' => 'Уключыць аўтазапаўненне адрасоў Brasil API для палёў CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Выкарыстоўвайце Brasil API для атрымання і аўтаматычнага запаўнення адрасоў з дапамогай поля CEP/паштовы індэкс. Тэрмінова толькі для бразільскіх адрасоў.','API version' => 'Версія API','Choose which version of the Brasil API CEP method to use.' => 'Выберыце, якую версію метаду Brasil API CEP выкарыстоўваць.','Address book migration' => 'Міграцыя адраснай кнігі','WooCommerce addresses' => 'Адрасы WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Скапіруйце існуючыя адрасы дастаўкі і выстаўлення рахункаў з WooCommerce у адрасную кнігу кліентаў.','Enable the address book feature' => 'Уключыць функцыю адраснай кнігі','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Дазвольце кліентам захоўваць некалькі адрасоў і вызначаць адрас па змаўчанні, які будзе выкарыстоўвацца для дастаўкі і выстаўлення рахункаў.','Address labels' => 'Адрасныя этыкеткі','Allow customers to add a custom label for each address' => 'Дазволіць кліентам дадаваць уласную этыкетку для кожнага адраса','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Адрасныя этыкеткі дазваляюць кліентам лягчэй адрозніваць захаваныя адрасы (напрыклад, «Дом мамы»). Адрасныя этыкеткі з&#39;яўляюцца прыватнымі для кліентаў і не будуць адлюстроўвацца або друкавацца на старонцы звестак пра заказ або ў рахунках-фактурах.','Display layout' => 'Макет дысплея','Choose how saved addresses are displayed at checkout and on the cart.' => 'Выберыце, як захаваныя адрасы будуць адлюстроўвацца пры афармленні замовы і ў кошыку.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Дзейнічае пры афармленні замовы і ў кошыку. Захаваныя адрасы на старонцы ўліковага запісу заўсёды выкарыстоўваюць макет картак.','Address cards' => 'Адрасныя карткі','Address list' => 'Спіс адрасоў','Dropdown field' => 'Выпадальнае поле','Address search' => 'Пошук па адрасе','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Паказваць фільтр пошуку адрасоў на інтэрфейсе, калі ў кліента ёсць хаця б такая колькасць захаваных адрасоў.','Not used when display layout is set to dropdown field.' => 'Не выкарыстоўваецца, калі макет адлюстравання ўсталяваны на выпадальнае поле.','Addresses' => 'Адрасы','Enable cart page optimizations to see more options' => 'Уключыце аптымізацыю старонкі кошыка, каб убачыць больш варыянтаў','Sticky order summary' => 'Замацаваны звод замовы','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Выберыце месца, дзе на старонцы кошыка трэба адлюстроўваць раздзел з кодамі купонаў. Дастасоўна толькі пры ўключаным кошыку AJAX і калі выкарыстанне кодаў купонаў уключана ў наладах WooCommerce.','Layout of cross-sell' => 'Макет перакрыжаваных продажаў','Cross-sells displayed' => 'Адлюстраванне перакрыжаваных продажаў','Items' => 'Прадметы','Cart page optimization' => 'Аптымізацыя старонкі кошыка','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Зрабіце свой кошык такім жа зразумелым, арыентаваным на канверсію, як і афармленне замовы.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Супастаўце макет кошыка са старонкай афармлення замовы для паслядоўнага працэсу пакупкі.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Заўсёды абнаўляйце кошык у фонавым рэжыме, не перазагружайце поўную старонку пры змене колькасці.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Размяшчайце коды купонаў, прапановы дастаўкі і перакрыжаваныя продажы менавіта там, дзе яны найлепш канвертуюць.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Захоўвайце зводку замовы бачнай падчас пракруткі і дадавайце сімвалы даверу там, дзе пакупнікам патрэбна падтрымка.','Columns' => 'Калонкі','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Агульныя стылі для этапаў афармлення замовы, звестак пра заказ і іншых раздзелаў. Тычыцца іншых старонак афармлення замовы, кошыка, падзякі (заказ атрыманы) і прагляду замовы.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Пры выкарыстанні макета <em>«1 калона»</em> з шаблонам дызайну <em>«Падзелены»</em> правы слупок адлюстроўваецца толькі ў тым выпадку, калі вобласць віджэта бакавой панэлі старонкі актыўная (бакавая панэль афармлення замовы, бакавая панэль кошыка або бакавая панэль атрыманага замовы). У адваротным выпадку старонка застаецца ў выглядзе аднаго слупка са стылямі «Падзелены».','Split column background' => 'Падзелены фон слупка','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Выберыце колер фону для другаснай калонкі «Падзелены дызайн». Пакіньце поле пустым, каб выкарыстоўваць колер фону зводкі замовы.','Page templates' => 'Шаблоны старонак','Checkout template' => 'Шаблон афармлення замовы','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Рэкамендуецца для меншай колькасці адцягваючых фактараў пры афармленні замовы. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Прачытайце даследаванне аб адмове ад кошыка</a> .','Sticky progress bar' => 'Заліпаная індыкатар прагрэсу','Progress bar style' => 'Стыль прагрэс-бар','Order totals' => 'Агульная сума замовы','Background color' => 'Колер фону','Action link' => 'Спасылка на дзеянне','Mobile order summary' => 'Зводка мабільнага замовы','Mobile initial state' => 'Пачатковы стан мабільнай прылады','Enable editing cart items at checkout' => 'Уключыць рэдагаванне тавараў у кошыку пры афармленні замовы','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Дазвольце кліентам змяняць колькасць тавараў або выдаляць тавары непасрэдна на старонцы афармлення замовы.','Cart item errors' => 'Памылкі тавараў у кошыку','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Дзейнічае толькі тады, калі код купона адлюстроўваецца асобным раздзелам на старонках афармлення замовы або кошыка, і калі выкарыстанне кодаў купонаў уключана ў наладах WooCommerce.','Coupon codes position' => 'Пазіцыя купонных кодаў','Apply coupon button' => 'Кнопка «Ужыць купон»','Select style of the "apply coupon" button.' => 'Выберыце стыль кнопкі «ўжыць купон».','Address line 2' => 'Радок адраса 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Гэты параметр агульны для раздзелаў «Афармленне замовы» і «Мясцовы самавываз». У раздзеле «Мясцовы самавываз» ён таксама вызначае, ці будзе селектар «Дастаўка/Самавываз» адлюстроўвацца ўнутры раздзела спосабу дастаўкі (перад адрасам) ці ў асобным раздзеле (пасля).','Customer accounts' => 'Рахункі кліентаў','Guest checkout' => 'Выезд госця','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Варыянты афармлення замовы, уваходу і стварэння ўліковага запісу для гасцей на старонцы налад уліковых запісаў WooCommerce. Яны кіруюцца тут для вашай зручнасці, таму вы можаце выкарыстоўваць розныя значэнні для кожнага профілю налад.','Allow customers to checkout without an account' => 'Дазволіць кліентам афармляць заказ без уліковага запісу','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Рэкамендуецца</strong> , каб кліентам не прапаноўвалася ствараць уліковы запіс або ўваходзіць у сістэму падчас афармлення замовы, што можа знізіць каэфіцыент канверсіі.','When disabled, customers must log in or create an account to complete the purchase.' => 'Калі гэтая функцыя адключана, кліенты павінны ўвайсці ў сістэму або стварыць уліковы запіс, каб завяршыць куплю.','Login at checkout' => 'Уваход пры афармленні замовы','Enable log-in during checkout' => 'Уключыць уваход падчас афармлення замовы','Show a link for returning customers to log in from the checkout page.' => 'Паказваць спасылку для пастаянных кліентаў для ўваходу ў сістэму са старонкі афармлення замовы.','Account creation' => 'Стварэнне ўліковага запісу','Allow customers to create an account during checkout' => 'Дазвольце кліентам стварыць уліковы запіс падчас афармлення замовы','Customers can create an account before placing their order.' => 'Кліенты могуць стварыць уліковы запіс перад афармленнем замовы.','Allow customers to create an account from the My account page' => 'Дазволіць кліентам ствараць уліковы запіс на старонцы «Мой уліковы запіс»','Customers can register a new account from the My account page.' => 'Кліенты могуць зарэгістраваць новы ўліковы запіс на старонцы «Мой уліковы запіс».','Username' => 'Імя карыстальніка','Generate from customer\'s name' => 'Згенераваць з імя кліента','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Рэкамендуецца</strong> , каб кліентам не прапаноўвалася выбіраць імя карыстальніка падчас афармлення замовы, што можа знізіць каэфіцыент канверсіі.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Імя карыстальніка генеруецца з імя кліента або з адраса электроннай пошты, калі імя выкарыстоўваць немагчыма.','Password' => 'Пароль','Send password setup link' => 'Адправіць спасылку для налады пароля','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Рэкамендуецца</strong> , каб кліенты не патрабавалі ўводзіць пароль падчас афармлення замовы, што можа знізіць каэфіцыент канверсіі.','Customers receive an email to create their password securely.' => 'Кліенты атрымліваюць электронны ліст для бяспечнага стварэння пароля.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Дазвольце зарэгістраваным кліентам афармляць заказ без уваходу ў сістэму і прывязваць заказ да іх існуючага ўліковага запісу, калі кантактныя дадзеныя супадаюць.','Existing account message' => 'Паведамленне пра існуючы ўліковы запіс','Let customers create an account after placing their order, from the thank you page.' => 'Дазвольце кліентам стварыць уліковы запіс пасля афармлення замовы на старонцы падзякі.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Опцыі ў гэтым раздзеле даступныя, калі ўключаны афармленне замовы госцем і супастаўленне ўліковых запісаў. Уключыце абедзве функцыі вышэй, каб наладзіць адкладзенае стварэнне ўліковага запісу.','Enable delayed account creation' => 'Уключыць адкладзенае стварэнне ўліковага запісу','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Уключыць адкладзенае стварэнне ўліковага запісу, калі ўключаны як афармленне замовы госцем, так і супастаўленне ўліковых запісаў.','Section position' => 'Пазіцыя раздзела','Before customer details section' => 'Раздзел з дадзенымі пра кліента перад','After customer details section' => 'Пасля раздзела з дадзенымі кліента','Account creation benefits' => 'Перавагі стварэння ўліковага запісу','Leaving the field empty will display the default text.' => 'Калі пакінуць поле пустым, будзе адлюстроўвацца тэкст па змаўчанні.','Inline buttons' => 'Убудаваныя кнопкі','Required fields' => 'Абавязковыя палі','Enable gift message fields at checkout' => 'Уключыць палі паведамленняў для падарунка пры афармленні замовы','Expanded gift message' => 'Пашыранае падарункавае паведамленне','Display gift message field always expanded' => 'Поле паведамлення падарунка заўсёды разгортваецца','Gift message in order details' => 'Падарункавае паведамленне ў падрабязнасцях замовы','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'У гэтым раздзеле пакуль няма даступных інтэграцый. Опцыі, звязаныя з кожным плагінам і тэмай, з&#39;явяцца тут толькі тады, калі гэты плагін або тэма актываваны.','Phone fields' => 'Палі тэлефона','Field visibility' => 'Бачнасць поля','Field position' => 'Пазіцыя на полі','Phone country code & validation' => 'Код краіны і праверка','Country' => 'Краіна','Enable country on phone fields' => 'Уключыць краіну ў палях тэлефона','Filter countries for shipping or billing' => 'Фільтраваць краіны для дастаўкі або аплаты','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Абмяжуйце выбар краіны ў кожным полі тэлефона краінамі, дазволенымі для дастаўкі або аплаты ў вашай краме.','Validation' => 'Праверка','Enable simple validation based on country rules' => 'Уключыць простую праверку на аснове правілаў краіны','Checks that the phone number is valid for the selected country, including country code and length.' => 'Правярае, ці сапраўдны нумар тэлефона для выбранай краіны, у тым ліку код краіны і даўжыню.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Больш строгая праверка таго, што нумар з&#39;яўляецца сапраўдным мабільным, стацыянарным або іншым тыпам, дазволеным для выбранай краіны. Некаторыя сапраўдныя нумары могуць быць адхіленыя.','Validation types' => 'Тыпы праверкі','Placeholders' => 'Запаўняльнікі','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'На дадзены момант няма ліцэнзійных ключоў для кіравання. Ліцэнзійныя ключы будуць адлюстроўвацца тут, калі актыўны ліцэнзаваны плагін або дадатак Fluid Checkout.','Default delivery type' => 'Тып дастаўкі па змаўчанні','Choose which delivery type will be selected by default.' => 'Выберыце, які тып дастаўкі будзе абраны па змаўчанні.','Shipping zone fields' => 'Палі зоны дастаўкі','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Выберыце, якія палі будуць адлюстроўвацца для фільтра зоны дастаўкі мясцовага самавывазу. Пакіньце поле пустым, каб паказаць усе даступныя варыянты.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Гэтыя палі будуць адлюстроўвацца ў якасці фільтра для мясцовых спосабаў дастаўкі з самавывазам. Некаторыя палі могуць усё яшчэ адлюстроўвацца пры афармленні замовы, калі яны не выбраны тут, калі сумяшчальныя плагіны патрабуюць іх правільнай працы.','Order shipping address' => 'Адрас дастаўкі замовы','Order pay page optimization' => 'Аптымізацыя старонкі аплаты замовы','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Дайце неаплачаным заказам такую ж зразумелую, арыентаваную на канверсію структуру, як і афармленне замовы.','Optimize the layout of the order pay page for orders pending payment.' => 'Аптымізуйце макет старонкі аплаты заказаў для заказаў, якія чакаюць аплаты.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Супастаўце аплату замовы з афармленнем замовы для паслядоўнага працэсу пакупкі.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Дадайце сімвалы даверу і значкі там, дзе пакупнікі павінны пераканацца перад аплатай.','Thank you page optimization' => 'Дзякуй за аптымізацыю старонкі','Make the thank you page and order details clearer for customers after they buy.' => 'Зрабіце старонку падзякі і інфармацыю пра заказ больш зразумелымі для кліентаў пасля таго, як яны зробяць пакупку.','Optimize the thank you page and account order details with a clearer layout.' => 'Аптымізуйце старонку падзякі і звесткі пра заказ у акаўнце з дапамогай больш зразумелага макета.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Паказвайце статус замовы, дзеянні, загрузкі і нататкі там, дзе гэта мае сэнс.','Customize order details sections on email notifications.' => 'Наладзьце раздзелы з падрабязнасцямі замовы ў апавяшчэннях па электроннай пошце.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Дадайце сімвалы даверу і значкі туды, дзе пакупнікам патрэбна падтрымка пасля пакупкі.','Email notifications' => 'Апавяшчэнні па электроннай пошце','Enable thank you page and order details optimizations to see more options' => 'Уключыце аптымізацыю старонкі падзякі і звестак пра заказ, каб бачыць больш варыянтаў','Use wide layout on thank you page' => 'Выкарыстоўвайце шырокі макет на старонцы падзякі','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Гэтыя параметры ўплываюць на старонку падзякі, прагляд звестак пра заказ на старонках уліковага запісу і на апавяшчэнні па электроннай пошце.','Save settings' => 'Захаваць налады','Docs' => 'Дакументы','Cart' => 'Кошык','Thank you' => 'Дзякуй','Address autocomplete' => 'Аўтазапаўненне адраса','Trust badges' => 'Значкі даверу','You do not have permission to save these settings.' => 'У вас няма дазволу на захаванне гэтых налад.','Invalid save request.' => 'Няправільны запыт на захаванне.','Your settings have been saved.' => 'Вашы налады захаваны.','Saving...' => 'Захаванне...','Settings could not be saved. Please try again.' => 'Не ўдалося захаваць налады. Паўтарыце спробу.','Dismiss notice' => 'Адхіліць паведамленне','Open settings menu' => 'Адкрыць меню налад','Close settings menu' => 'Закрыць меню налад','Preview' => 'Папярэдні прагляд','Expand preview' => 'Разгарнуць папярэдні прагляд','Collapse preview' => 'Згарнуць папярэдні прагляд','Show header and footer' => 'Паказаць верхні і ніжні калантытулы','Hide header and footer' => 'Схаваць верхні і ніжні калантытулы','Page preview' => 'Папярэдні прагляд старонкі','Preview viewport' => 'Папярэдні прагляд вобласці прагляду','Tablet' => 'Планшэт','Desktop' => 'Настольны кампутар','Preview width' => 'Шырыня папярэдняга прагляду','Decrease width' => 'Паменшыць шырыню','Preview width in pixels' => 'Шырыня папярэдняга прагляду ў пікселях','Increase width' => 'Павялічыць шырыню','Preview as' => 'Папярэдні прагляд як','Guest' => 'Госць','Logged in' => 'Увайшоў у сістэму','Preview page' => 'Старонка папярэдняга прагляду','Expand preview for a closer look' => 'Разгарнуць папярэдні прагляд для больш падрабязнага прагляду','Available with %s.' => 'Даступна з %s.','Turn them on' => 'Уключыце іх','Optimizations for this page are turned off. %s to preview the page.' => 'Аптымізацыя для гэтай старонкі адключана. %s для папярэдняга прагляду старонкі.','%s preview' => 'Папярэдні прагляд %s','Isolated session · nothing is saved' => 'Ізаляваны сеанс · нічога не захоўваецца','Usage tracking' => 'Адсочванне выкарыстання','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Адпраўляць неканфідэнцыйныя справаздачы аб асяроддзі сайта, каб дапамагчы Fluid Checkout палепшыць сумяшчальнасць. Справаздачы не адпраўляюцца, пакуль яны не ўключаны ў наступных параметрах.','Send usage tracking reports to Fluid Checkout' => 'Адпраўляць справаздачы аб адсочванні выкарыстання ў Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Гэтыя справаздачы дапамагаюць нам палепшыць сумяшчальнасць і падтрымку вашага сайта і адпраўляюцца штотыдзень, калі яны ўключаны.','No customer, admin user, or any other sensitive data is included in the reports.' => 'У справаздачы не ўключаюцца дадзеныя кліентаў, адміністратараў і іншыя канфідэнцыйныя дадзеныя.','Basic environment info' => 'Асноўная інфармацыя пра асяроддзе','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Дадзеныя спісу WordPress, PHP, WooCommerce, тэм і плагінаў. Заўсёды ўключаюцца, калі ўключана справаздачнасць. Дапамагае нам зразумець асяроддзе, у якім працуе ваш сайт.','Plugin settings' => 'Налады плагіна','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Адпраўляе налады плагіна Fluid Checkout, каб дапамагчы з запытамі падтрымкі і зразумець, як вы выкарыстоўваеце нашы плагіны.','Coming soon' => 'Хутка','Sales metrics' => 'Паказчыкі продажаў','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Штомесячная колькасць заказаў і агульны аб&#39;ём продажаў за год да ўсталёўкі Fluid Checkout па сённяшні дзень. Дапамагае нам зразумець, ці зарабляеце вы больш грошай з усталяванымі нашымі плагінамі. Дадзеныя кліентаў або карыстальнікаў ніколі не адпраўляюцца.','Utilities' => 'Камунальныя паслугі','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Выкарыстоўвайце выпадальныя кампаненты <code>TomSelect</code> замест <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect — гэта больш просты кампанент выпадальнага спісу, які менш схільны да памылак, чым Select2, але прапануе тую ж функцыянальнасць.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Устанаўлівае памер шрыфта ўнутры палёў формы на 16 пікселяў на старонках, аптымізаваных гэтым убудовай, каб пазбегнуць аўтаматычнага павелічэння маштабу пры ўзаемадзеянні з палямі формы на невялікіх прыладах.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari і іншыя браўзеры могуць аўтаматычна павялічваць маштаб на мабільных прыладах, каб зрабіць тэкст лягчэйшым для чытання, калі памер шрыфта меншы за 16 пікселяў.','Enable script processing tracking on the browser console.' => 'Уключыць адсочванне апрацоўкі скрыптоў у кансолі браўзера.','Unminified assets' => 'Немініфікаваныя актывы','Google Maps scripts' => 'Скрыпты Google Maps','Do not remove duplicate Google Maps scripts' => 'Не выдаляць дублікаты скрыптоў Google Maps','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Калі гэтая опцыя ўключана, дублікаты скрыптоў Google Maps НЕ будуць выдалены, што можа прывесці да памылак і праблем з прадукцыйнасцю. Выкарыстоўвайце гэту опцыю толькі падчас ліквідацыі непаладак.','Widget areas' => 'Вобласці віджэтаў','Last step on mobile' => 'Апошні крок на мабільным тэлефоне','Display widgets only at last step on mobile' => 'Паказваць віджэты толькі на апошнім кроку на мабільным тэлефоне','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Паказваць віджэты значка даверу пры афармленні замовы толькі пры праглядзе апошняга кроку афармлення замовы на мабільных прыладах','Standard' => 'Стандартны','VAT number field' => 'Поле нумара ПДВ','Add a VAT number field to the billing form.' => 'Дадайце поле нумара ПДВ у форму выстаўлення рахункаў.','Field label' => 'Пазнака поля','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Усталюйце пазнаку поля нумара ПДВ (напрыклад, нумар ПДВ). На шматмоўных сайтах лепш пакінуць гэтае поле пустым і перакласці зыходны радок.','VAT Number' => 'Нумар ПДВ','EU-VAT' => 'ПДВ ЕС','Enable the VAT number field to see more options' => 'Уключыце поле нумара ПДВ, каб убачыць больш варыянтаў','VAT validation' => 'Пацверджанне ПДВ','Validate VAT number field for EU-VAT during checkout' => 'Пацвердзіць поле нумара ПДВ для ЕС-ПДВ падчас афармлення замовы','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Правярае, ці з&#39;яўляецца прадстаўлены нумар ПДВ сапраўдным нумарам ПДВ, зарэгістраваным у еўрапейскай базе дадзеных VIES (сістэма абмену інфармацыяй па ПДВ).','Shop VAT number' => 'Нумар ПДВ крамы','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Нумар ПДВ крамы, які выкарыстоўваецца для запыту на праверку ПДВ ЕС і друкуецца ў рахунках-фактурах.<br> <strong>Мы настойліва раім дадаць нумар ПДВ вашай крамы</strong> , бо ў адваротным выпадку вынікі кансультацыі VIES могуць быць несапраўднымі для бухгалтарскага ўліку.<br> Гэта значыць: <code>ATU99999999</code> або <code>EE999999999</code> .','Reverse charge' => 'Зваротнае спагнанне','Apply reverse charge mechanism' => 'Ужыць механізм адваротнага спагнання','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Усталюйце падатковую стаўку роўнай нулю і адлюстроўвайце ў рахунках-фактурах &quot;Зваротнае спагнанне&quot;, калі нумар ПДВ кліента сапраўдны. У залежнасці ад краіны крамы можа спатрэбіцца іншы тэкст &quot;Зваротнага спагнання&quot;.','Same country' => 'Тая ж краіна','Apply reverse charge mechanism for transactions in the shop country:' => 'Ужывайце механізм адваротнага спагнання для транзакцый у краіне, дзе прадаецца крама:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Дазваляе ўжываць механізм адваротнага спагнання падаткаў для транзакцый паміж кампаніямі ў той жа краіне, што і крама.','Reverse charge exceptions' => 'Выключэнні з адваротнага спагнання','Select additional countries to skip applying the reverse charge mechanism.' => 'Выберыце дадатковыя краіны, каб прапусціць прымяненне механізму адваротнага падаткаабкладання.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Падаткі будуць спаганяцца з заказаў з гэтых краін, нават калі прадастаўлены сапраўдны нумар ПДВ.','Reverse charge label on invoices' => 'Пазнака зваротнага аплаты на рахунках-фактурах','Set the label of "reverse charge" on the checkout page and order details.' => 'Усталюйце пазнаку «зваротнае аплата» на старонцы афармлення замовы і ў падрабязнасцях.','Reverse charge text on invoices' => 'Тэкст зваротнага аплаты ў рахунках-фактурах','Set the label of "reverse charge" text on invoices.' => 'Усталюйце на рахунках-фактурах надпіс «зваротнае аплата».','Tax to be paid on reverse charge basis' => 'Падатак, які падлягае выплаце на ўмовах адваротнага налічэння падатку','Company name' => 'Назва кампаніі','Autocomplete company name from VAT number' => 'Аўтазапаўненне назвы кампаніі з нумара ПДВ','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Запоўніце назву плацежнай кампаніі ў адпаведнасці з дзеючым нумарам ПДВ, прадастаўленым кліентам.','Company name editing' => 'Рэдагаванне назвы кампаніі','Allow editing of auto-filled company name' => 'Дазволіць рэдагаванне аўтаматычна запоўненай назвы кампаніі','When enabled, customers can change the company name associated with the provided VAT number.' => 'Калі гэтая функцыя ўключана, кліенты могуць змяніць назву кампаніі, звязаную з указаным нумарам ПДВ.','EU-VAT for digital goods' => 'ПДВ ЕС для лічбавых тавараў','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'З 1 студзеня 2015 года ў правілы ЕС па ПДВ адносна лічбавых тавараў былі ўнесены змены, якія закранаюць выключна транзакцыі B2C. ПДВ на лічбавыя тавары павінен разлічвацца ў залежнасці ад месцазнаходжання кліента, і неабходна сабраць доказы гэтага (IP-адрас і адрас для выстаўлення рахункаў).','Tax classes for digital goods' => 'Падатковыя класы для лічбавых тавараў','Select some tax classes' => 'Выберыце некалькі падатковых класаў','Location evidence' => 'Доказы месцазнаходжання','Collect customer\'s location evidence' => 'Збярыце доказы месцазнаходжання кліента','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Захоўвае IP-адрас і правярае яго адносна плацежнага адраса кліента. Кліент павінен пацвердзіць свой плацежны адрас, паставіўшы галачку на старонцы афармлення замовы, калі краіна ў плацежным адрасе і IP-адрасе не супадаюць.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Гэтая опцыя кіруецца ў Fluid Checkout. <a href="%s">Змяніце яе ў наладах уліковага запісу кліента</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Гэтая опцыя кіруецца ў Fluid Checkout. Змяніце яе ў раздзеле Fluid Checkout &gt; Рахункі кліентаў.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Гэтая опцыя кіруецца ў Fluid Checkout. Пры актывацыі Fluid Checkout пунктам прызначэння дастаўкі заўсёды ўстаноўлена «Адрас дастаўкі па змаўчанні па кліенту». Кліенты ўсё яшчэ могуць указваць розныя адрасы дастаўкі і плацежныя адрасы падчас афармлення замовы.<br><br> У <a href="%s">наладах Fluid Checkout</a> даступная опцыя, якая дазваляе ўсталяваць адрас для аплаты па змаўчанні такім жа, як і адрас дастаўкі.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Гэтая опцыя кіруецца ў Fluid Checkout. Пры актывацыі Fluid Checkout пунктам прызначэння дастаўкі заўсёды ўстаноўлена «Адрас дастаўкі па змаўчанні па кліенту». Кліенты ўсё яшчэ могуць указваць розныя адрасы дастаўкі і плацежныя адрасы падчас афармлення замовы.<br><br> Опцыя для ўстаноўкі адраса для выстаўлення рахункаў па змаўчанні такім жа, як і адрас дастаўкі, даступная ў WooCommerce &gt; Налады &gt; Плаўнае афармленне замовы.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Гэтыя налады былі перамешчаны ў раздзел WP Admin &gt; Fluid Checkout &gt; Налады.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Гэтая ўкладка «Налады WooCommerce» састарэла і будзе выдалена ў Fluid Checkout 6.0.','Go to settings page' => 'Перайсці на старонку налад','Hide this tab permanently' => 'Схаваць гэтую ўкладку назаўсёды','Site report preview' => 'Папярэдні прагляд справаздачы па сайце','This is the data that would be included in the next site environment report based on your current settings.' => 'Гэта даныя, якія будуць уключаны ў наступную справаздачу аб асяроддзі сайта ў залежнасці ад вашых бягучых налад.','Loading report preview...' => 'Загрузка папярэдняга прагляду справаздачы...','Could not load the site report preview. Try again.' => 'Не атрымалася загрузіць папярэдні прагляд справаздачы па сайце. Паспрабуйце яшчэ раз.','Could not send the site report. Try again.' => 'Не атрымалася адправіць справаздачу аб сайце. Паспрабуйце яшчэ раз.','Site report sent successfully.' => 'Справаздача аб сайце паспяхова адпраўлена.','Enable and send now' => 'Уключыць і адправіць зараз','Close' => 'Закрыць','A site report request is already in progress. Try again in a moment.' => 'Запыт на справаздачу аб сайце ўжо апрацоўваецца. Паўтарыце спробу праз хвіліну.','Site environment reporting is disabled.' => 'Справаздачнасць аб асяроддзі сайта адключана.','No site report data is available to send.' => 'Няма дадзеных справаздачы аб сайце для адпраўкі.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Гэты дамен сайта не можа адпраўляць справаздачы аб навакольным асяроддзі (лакальныя або распрацоўчыя дамены выключаны).','A site report was sent recently. Try again later.' => 'Нядаўна была адпраўлена справаздача аб стане сайта. Паўтарыце спробу пазней.','The site report could not be sent. Try again later.' => 'Не ўдалося адправіць справаздачу аб сайце. Паўтарыце спробу пазней.','Site environment reporting is not available.' => 'Справаздачнасць аб асяроддзі сайта недаступная.','No site report data is available for the selected settings.' => 'Для выбраных налад няма дадзеных справаздачы аб сайце.','You are not allowed to manage site reports.' => 'Вам не дазволена кіраваць справаздачамі па сайтах.','PRO feature' => 'PRO-функцыя','Other plugins' => 'Іншыя плагіны','Get only this add-on &mdash; %s' => 'Атрымаць толькі гэта дадатак — %s','Install add-on' => 'Усталяваць дадатак','Upgrade to PRO &mdash; %s' => 'Абнавіць да PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Атрымайце %2$s</a> , каб разблакіраваць гэтыя опцыі.','Add-on' => 'Дадатак','View documentation' => 'Праглядзець дакументацыю','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Для запытаў патрабуецца зарэгістраваны карыстальнік WordPress. Каб выкарыстоўваць дадзеныя бягучага карыстальніка, прапусціце параметр user_id або перадайце параметр user_id, каб звярнуцца да іншага ўліковага запісу, калі выклікаючая асоба можа рэдагаваць гэтага карыстальніка (магчымасць edit_user). Неаўтэнтыфікаваныя запыты вяртаюць fc_api_forbidden. Няправільны user_id вяртае fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 з { &quot;data&quot;: { ... } }, калі апрацоўшчык вяртае карысную нагрузку.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 з { &quot;success&quot;: true }, калі няма карыснай нагрузкі (напрыклад, DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Памылкі вяртаюць памылку WordPress REST у фармаце JSON з WP_Error (code, message, data.status). Коды перадачы дадзеных выкарыстоўваюць прэфікс fc_api_*.','Forbidden access.' => 'Забаронены доступ.','Target user was not found.' => 'Мэтавы карыстальнік не знойдзены.','This feature is not available.' => 'Гэтая функцыя недаступная.','A required address field is missing.' => 'Абавязковае поле адраса адсутнічае.','Postcode or ZIP is invalid.' => 'Паштовы індэкс няправільны.','Phone number is invalid.' => 'Нумар тэлефона несапраўдны.','State or county is invalid.' => 'Штат або акруга несапраўдныя.','Country is invalid or has no address fields.' => 'Краіна няправільная або не мае палёў адраса.','The request could not be processed.' => 'Запыт не мог быць апрацаваны.','Back to previous step' => 'Назад да папярэдняга кроку','Skip to settings' => 'Перайсці да налад','Start over and return to the first guided setup step' => 'Пачаць спачатку і вярнуцца да першага кроку налады з інструкцыяй','Start over' => 'Пачаць спачатку','Please complete all sub-steps before continuing.' => 'Калі ласка, выканайце ўсе падэтапы, перш чым працягнуць.','Expand' => 'Разгарнуць','Collapse' => 'Згарнуць','Skip' => 'Прапусціць','Mark as complete' => 'Адзначыць як завершанае','Mark as incomplete' => 'Пазначыць як няскончанае','View full-size image: %s' => 'Паглядзець выяву ў поўным памеры: %s','Full-size setup guide image' => 'Поўнапамернае малюнак кіраўніцтва па ўсталёўцы','Close image' => 'Закрыць выяву','Fluid Checkout Guided Setup' => 'Кіраваная налада праверкі вадкасці','Welcome' => 'Сардэчна запрашаем','Explore your checkout' => 'Азнаёмцеся з афармленнем замовы','All set' => 'Усё гатова','You do not have permission to access this page.' => 'У вас няма дазволу на доступ да гэтай старонкі.','Go to step %1$d: %2$s' => 'Перайсці да кроку %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Гэтая інструкцыя па наладзе дапаможа вам азнаёміцца з функцыяй Fluid Checkout. Прыведзеныя ніжэй крокі пакуль што з&#39;яўляюцца прыкладам.','Continue to the next step when you are ready.' => 'Пераходзьце да наступнага кроку, калі будзеце гатовыя.','Open your store checkout to see Fluid Checkout in action.' => 'Адкрыйце касу вашай крамы, каб убачыць Fluid Checkout у дзеянні.','View checkout page' => 'Праглядзець старонку афармлення замовы','You can return to Fluid Checkout settings to continue configuring your store.' => 'Вы можаце вярнуцца да налад Fluid Checkout, каб працягнуць канфігурацыю вашай крамы.','Review checkout and cart settings' => 'Праглядзіце налады афармлення замовы і кошыка','Explore add-ons from the dashboard' => 'Азнаёмцеся з дапаўненнямі з панэлі кіравання','Finish & go to settings' => 'Завяршыць і перайсці да налад','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Абнавіце параметр бачнасці поля нумара тэлефона для выстаўлення рахункаў з старога значэння, каб ён адпавядаў канвенцыям WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Абнавіце параметр бачнасці поля тэлефона дастаўкі з старога значэння, каб ён адпавядаў канвенцыям WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Скапіруйце наладу колеру фону зводкі замовы ў новы параметр колеру фону другаснай калонкі «Падзелены дызайн».','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Палепшаная функцыя выбару палёў заўсёды адключана пры выкарыстанні плагіна Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Пры выкарыстанні нямецкага рынку пазіцыя размяшчэння замовы заўсёды ўстаноўлена на «Пад зводкай замовы». Гэты плагін патрабуе, каб кнопка размяшчэння замовы і юрыдычныя сцяжкі адлюстроўваліся пад зводкай замовы.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Пры выкарыстанні Germanized для WooCommerce пазіцыя размяшчэння замовы заўсёды ўстаноўлена на «Пад апісаннем замовы». Гэты плагін патрабуе, каб кнопка размяшчэння замовы і юрыдычныя сцяжкі адлюстроўваліся пад апісаннем замовы.','Edit pickup locations' => 'Рэдагаваць месцы пасадкі','Use local pickup label from WooCommerce settings' => 'Выкарыстоўваць мясцовы этыкетку самавывазу з налад WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Калі ўключана, надпіс варыянту самавывазу пры афармленні замовы супадае з назвай з налад месца самавывазу WooCo